-- ===== 0002_ticket_photos.sql =====
-- Photos for tickets (intake photos now; before/after in a later phase)

create table public.ticket_photos (
  id uuid primary key default gen_random_uuid(),
  ticket_id uuid not null references public.tickets(id) on delete cascade,
  storage_path text not null,
  kind text not null default 'intake' check (kind in ('intake', 'before', 'after')),
  caption text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now()
);
create index on public.ticket_photos (ticket_id, created_at);

alter table public.ticket_photos enable row level security;

-- Insert and read only. Photos can't be edited or deleted from the app, so the
-- intake record stays trustworthy. (You can still remove one in the Supabase dashboard.)
create policy "staff read"   on public.ticket_photos for select to authenticated using (true);
create policy "staff insert" on public.ticket_photos for insert to authenticated with check (true);

-- Private storage bucket for the image files
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('ticket-photos', 'ticket-photos', false, 10485760,
        array['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif'])
on conflict (id) do nothing;

create policy "photos read"   on storage.objects for select to authenticated using (bucket_id = 'ticket-photos');
create policy "photos upload" on storage.objects for insert to authenticated with check (bucket_id = 'ticket-photos');

-- ===== 0003_dashboard.sql =====
-- Dashboard support: which statuses mean "repair finished", and when each ticket got there.

alter table public.statuses add column is_done boolean not null default false;
alter table public.tickets  add column completed_at timestamptz;

-- Defaults for the starter workflow. Change them any time under Statuses in the app.
update public.statuses set is_done = true where is_closed or name in ('Completed', 'Ready for pickup');

-- Backfill existing tickets that are already in a finished status.
update public.tickets t
   set completed_at = coalesce(t.closed_at, t.updated_at)
  from public.statuses s
 where s.id = t.status_id and s.is_done and t.completed_at is null;

-- ===== 0004_parts.sql =====
-- Parts inventory, parts used per ticket, and labor charge for profit tracking.

create table public.parts (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  sku text,
  supplier text,
  cost_cents int not null default 0,       -- what you pay per unit
  price_cents int not null default 0,      -- what you usually charge per unit
  stock int not null default 0 check (stock >= 0),
  low_stock_at int not null default 2,     -- flagged when stock is at or below this
  notes text,
  archived boolean not null default false,
  created_at timestamptz not null default now()
);

-- Cost and price are copied onto each line, so later price changes never rewrite old tickets.
create table public.ticket_parts (
  id uuid primary key default gen_random_uuid(),
  ticket_id uuid not null references public.tickets(id) on delete cascade,
  part_id uuid references public.parts(id) on delete set null,   -- null for one-off parts not in inventory
  name text not null,
  qty int not null check (qty > 0),
  unit_cost_cents int not null default 0,
  unit_price_cents int not null default 0,
  created_at timestamptz not null default now()
);
create index on public.ticket_parts (ticket_id);
create index on public.ticket_parts (part_id);

alter table public.tickets add column labor_cents int;

alter table public.parts        enable row level security;
alter table public.ticket_parts enable row level security;
create policy "staff all" on public.parts        for all to authenticated using (true) with check (true);
create policy "staff all" on public.ticket_parts for all to authenticated using (true) with check (true);

-- Using a part takes it out of stock in the same transaction.
create or replace function public.add_ticket_part(p_ticket uuid, p_part uuid, p_qty int, p_price int default null)
returns void language plpgsql as $$
declare part public.parts%rowtype;
begin
  if p_qty is null or p_qty < 1 then raise exception 'Quantity must be at least 1'; end if;
  select * into part from public.parts where id = p_part for update;
  if not found then raise exception 'Part not found'; end if;
  if part.stock < p_qty then
    raise exception 'Only % of % in stock', part.stock, part.name;
  end if;
  update public.parts set stock = stock - p_qty where id = p_part;
  insert into public.ticket_parts (ticket_id, part_id, name, qty, unit_cost_cents, unit_price_cents)
  values (p_ticket, p_part, part.name, p_qty, part.cost_cents, coalesce(p_price, part.price_cents));
  update public.tickets set updated_at = now() where id = p_ticket;
end $$;

-- Removing a line puts inventory parts back in stock.
create or replace function public.remove_ticket_part(p_line uuid)
returns void language plpgsql as $$
declare line public.ticket_parts%rowtype;
begin
  select * into line from public.ticket_parts where id = p_line for update;
  if not found then return; end if;
  if line.part_id is not null then
    update public.parts set stock = stock + line.qty where id = line.part_id;
  end if;
  delete from public.ticket_parts where id = p_line;
  update public.tickets set updated_at = now() where id = line.ticket_id;
end $$;

grant execute on function public.add_ticket_part(uuid, uuid, int, int) to authenticated;
grant execute on function public.remove_ticket_part(uuid) to authenticated;

-- ===== 0005_invoices.sql =====
-- Invoices, payments, and an unguessable token for the customer pay page.

create sequence public.invoice_number_seq start 5001;

create table public.invoices (
  id uuid primary key default gen_random_uuid(),
  invoice_number int not null unique default nextval('public.invoice_number_seq'),
  ticket_id uuid not null unique references public.tickets(id) on delete cascade,
  customer_id uuid not null references public.customers(id),
  tax_percent numeric(6,3) not null default 0 check (tax_percent >= 0),
  notes text,
  status text not null default 'open' check (status in ('open', 'void')),
  pay_token uuid not null unique default gen_random_uuid(),
  issued_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);

create table public.invoice_items (
  id uuid primary key default gen_random_uuid(),
  invoice_id uuid not null references public.invoices(id) on delete cascade,
  description text not null,
  qty int not null default 1 check (qty > 0),
  unit_price_cents int not null default 0,
  position int not null default 0
);
create index on public.invoice_items (invoice_id, position);

create table public.payments (
  id uuid primary key default gen_random_uuid(),
  invoice_id uuid not null references public.invoices(id) on delete cascade,
  amount_cents int not null check (amount_cents > 0),
  method text not null check (method in ('card', 'cash', 'stripe', 'other')),
  note text,
  stripe_session_id text unique,   -- makes online payments safe to record twice
  paid_at timestamptz not null default now(),
  created_by uuid default auth.uid()
);
create index on public.payments (invoice_id);

alter table public.invoices      enable row level security;
alter table public.invoice_items enable row level security;
alter table public.payments      enable row level security;
create policy "staff all" on public.invoices      for all to authenticated using (true) with check (true);
create policy "staff all" on public.invoice_items for all to authenticated using (true) with check (true);
create policy "staff all" on public.payments      for all to authenticated using (true) with check (true);

grant usage on sequence public.invoice_number_seq to authenticated;

-- ===== 0006_notifications.sql =====
-- Customer notifications: per-status templates, customer preferences, a public tracking token, and a send log.

alter table public.statuses
  add column notify_email boolean not null default false,
  add column email_subject text not null default '',
  add column email_body text not null default '',
  add column notify_sms boolean not null default false,
  add column sms_body text not null default '';

alter table public.customers
  add column notify_email boolean not null default true,     -- email status updates allowed
  add column sms_opt_in boolean not null default false;       -- customer agreed to text messages

-- Unguessable id for the customer-facing status page (existing tickets get one too).
alter table public.tickets add column track_token uuid not null default gen_random_uuid() unique;

create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  ticket_id uuid not null references public.tickets(id) on delete cascade,
  customer_id uuid references public.customers(id) on delete set null,
  channel text not null check (channel in ('email', 'sms')),
  to_address text not null default '',
  subject text,
  body text not null,
  status text not null check (status in ('sent', 'failed', 'skipped')),
  error text,
  provider_id text,
  created_at timestamptz not null default now()
);
create index on public.notifications (ticket_id, created_at desc);

alter table public.notifications enable row level security;
create policy "staff all" on public.notifications for all to authenticated using (true) with check (true);

-- Starter wording for the default stages. Nothing is switched on: enable stages under Settings > Notifications.
update public.statuses set
  email_subject = 'We received your {{device}}',
  email_body = E'Hi {{first_name}},\n\nWe''ve received your {{device}} (ticket #{{ticket_number}}). We''ll let you know once we''ve looked it over.\n\nYou can check progress any time: {{status_link}}\n\n{{shop_name}}',
  sms_body = '{{shop_name}}: we received your {{device}} (ticket #{{ticket_number}}). Status: {{status_link}}'
where name = 'Received';

update public.statuses set
  email_subject = 'We''re diagnosing your {{device}}',
  email_body = E'Hi {{first_name}},\n\nWe''re now diagnosing your {{device}} (ticket #{{ticket_number}}). We''ll be in touch with what we find.\n\nProgress: {{status_link}}\n\n{{shop_name}}',
  sms_body = '{{shop_name}}: we''re diagnosing your {{device}}. Status: {{status_link}}'
where name = 'Diagnosing';

update public.statuses set
  email_subject = 'Waiting on a part for your {{device}}',
  email_body = E'Hi {{first_name}},\n\nYour {{device}} (ticket #{{ticket_number}}) needs a part that we''ve ordered. We''ll update you when it arrives and work continues.\n\nProgress: {{status_link}}\n\n{{shop_name}}',
  sms_body = '{{shop_name}}: your {{device}} is waiting on a part. Status: {{status_link}}'
where name = 'Waiting for parts';

update public.statuses set
  email_subject = 'Work has started on your {{device}}',
  email_body = E'Hi {{first_name}},\n\nWe''ve started repairing your {{device}} (ticket #{{ticket_number}}).\n\nProgress: {{status_link}}\n\n{{shop_name}}',
  sms_body = '{{shop_name}}: repair has started on your {{device}}. Status: {{status_link}}'
where name = 'In progress';

update public.statuses set
  email_subject = 'Your {{device}} repair is complete',
  email_body = E'Hi {{first_name}},\n\nGood news: the repair on your {{device}} (ticket #{{ticket_number}}) is complete. We''ll confirm as soon as it''s ready for pickup.\n\n{{status_link}}\n\n{{shop_name}}',
  sms_body = '{{shop_name}}: your {{device}} repair is complete. Details: {{status_link}}'
where name = 'Completed';

update public.statuses set
  email_subject = 'Your {{device}} is ready for pickup',
  email_body = E'Hi {{first_name}},\n\nYour {{device}} (ticket #{{ticket_number}}) is ready for pickup.\n\nDetails and any balance: {{status_link}}\n\n{{shop_name}}',
  sms_body = '{{shop_name}}: your {{device}} is ready for pickup. Details: {{status_link}}'
where name = 'Ready for pickup';

